import json

with open('json/circuits.json', 'r') as f:
    data = json.load(f)

# Get all circuits with their circuitId and country
circuits_by_id = {}
for record in data['records']:
    circuits_by_id[record['circuitId']] = {
        'name': record['name'],
        'country': record['country']
    }

# Circuit IDs from European Grand Prix races
european_gp_circuit_ids = [12, 20, 26, 31, 38, 73]

print("Circuit details for European Grand Prix:")
germany_count = 0
total_european_gps = len(european_gp_circuit_ids)

for cid in european_gp_circuit_ids:
    if cid in circuits_by_id:
        info = circuits_by_id[cid]
        print(f"  Circuit ID {cid}: {info['name']} - Country: {info['country']}")
        if info['country'] == 'Germany':
            germany_count += 1
    else:
        print(f"  Circuit ID {cid}: NOT FOUND")

print(f"\nTotal European GP races (distinct circuits): {total_european_gps}")
print(f"European GP races hosted in Germany: {germany_count}")
print(f"Percentage: {(germany_count / total_european_gps) * 100:.2f}%")

